import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME || '/home/runner', '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const context = await browser.newContext({ viewport: { width: 1280, height: 720 } })
const page = await context.newPage()
const errors = []
page.on('pageerror', e => errors.push(`pageerror: ${e.message}`))
page.on('console', m => { if (m.type() === 'error') errors.push(`console: ${m.text()}`) })
await page.route('**/src/game.js', async route => {
  const response = await route.fetch()
  const original = await response.text()
  const instrumented = `${original}\nwindow.__facilityTest={game,player,interact,update,nearInteraction,getAudio:()=>({ctx:audioCtx,masterGain,ambienceGain}),getLiftDoors:()=>liftDoors};`
  await route.fulfill({ response, body: instrumented })
})
const response = await page.goto('http://127.0.0.1:8765/?playtest=1', { waitUntil: 'load', timeout: 45000 })
if (!response?.ok()) throw new Error(`Load failed: ${response?.status()}`)
await page.waitForFunction(() => window.__facilityTest && document.querySelector('#main-menu h1')?.textContent?.trim())
const tests = []
const check = (condition, name, detail='') => { tests.push({ name, pass: !!condition, detail }); if (!condition) throw new Error(`${name} failed${detail ? `: ${detail}` : ''}`) }
// Sound controls should initialize one shared audio context/master gain and change its value.
await page.locator('#sound-toggle').click()
check(await page.locator('#sound-toggle').getAttribute('aria-pressed') === 'false', 'sound toggle mutes')
await page.locator('#sound-toggle').click()
check(await page.locator('#sound-toggle').getAttribute('aria-pressed') === 'true', 'sound toggle unmutes')
await page.locator('[data-action="settings"]').click()
const volume = page.locator('#volume-slider')
await volume.evaluate(el => { el.value = '35'; el.dispatchEvent(new Event('input', { bubbles: true })) })
await page.waitForTimeout(100)
const gainBefore = await page.evaluate(() => window.__facilityTest.getAudio().masterGain?.gain.value)
check(Math.abs(gainBefore - .35) < .02, 'master volume slider updates gain', String(gainBefore))
await page.locator('[data-action="back"]').click()
await page.locator('[data-action="intro"]').click()
await page.locator('#skip-intro').click()
await page.waitForFunction(() => window.__facilityTest.game.mode === 'playing')
await page.waitForTimeout(100)
const sceneGain = await page.evaluate(() => window.__facilityTest.getAudio().ambienceGain?.gain.value)
check(sceneGain > 0, 'gameplay starts ambience bed', String(sceneGain))
mkdirSync('/tmp/opencode', { recursive: true })
await page.screenshot({ path: '/tmp/opencode/facility-verification.jpg', type: 'jpeg', quality: 82, fullPage: false })
// Exercise the real call/timer/door/return interaction while bypassing the long keycard route.
await page.evaluate(() => {
  const t = window.__facilityTest
  t.game.power = true
  t.game.detonation = 0
  t.player.pos.set(3.35, 0, -82)
  t.interact()
})
let callState = await page.evaluate(() => ({ called: window.__facilityTest.game.called, hold: window.__facilityTest.game.hold, phase: window.__facilityTest.game.phase }))
check(callState.called && callState.hold === 60, 'panel starts the 60-second survival sequence', JSON.stringify(callState))
const threatAudio = await page.evaluate(() => window.__facilityTest.getAudio().ambienceGain.gain.value)
check(threatAudio > sceneGain, 'elevator call intensifies ambience', `${sceneGain} -> ${threatAudio}`)
await page.evaluate(() => { const t=window.__facilityTest; t.game.detonation=0; if (t.game.monster) t.game.monster.userData.active=false; for(let i=0;i<120;i++) t.update(.5) })
let timerState = await page.evaluate(() => ({ hold: window.__facilityTest.game.hold, elapsed: window.__facilityTest.game.escapeElapsed, doors: window.__facilityTest.getLiftDoors().map(d => ({ x: d.mesh.position.x, disabled: d.collider.disabled })) }))
check(timerState.hold === 0, '60-second timer expires', JSON.stringify(timerState))
await page.evaluate(() => { const t=window.__facilityTest; t.game.detonation=0; t.update(1.05) })
timerState = await page.evaluate(() => ({ elapsed: window.__facilityTest.game.escapeElapsed, doors: window.__facilityTest.getLiftDoors().map(d => ({ x: d.mesh.position.x, disabled: d.collider.disabled })) }))
check(timerState.doors.every(d => d.disabled) && timerState.doors.every(d => Math.abs(d.x) > 2), 'elevator doors slide open and clear collision', JSON.stringify(timerState))
await page.evaluate(() => { const t=window.__facilityTest; t.game.detonation=0; t.player.pos.set(3.35,0,-82); t.interact() })
const ending = await page.evaluate(() => ({ mode: window.__facilityTest.game.mode, title: document.querySelector('#ending-title')?.textContent, visible: document.querySelector('#ending-screen')?.classList.contains('show') }))
check(ending.mode === 'ending' && ending.visible && ending.title.includes('OBERFLÄCHE'), 'return to panel wins the sequence', JSON.stringify(ending))
check(errors.length === 0, 'browser has no errors', errors.join(' | '))
console.log(JSON.stringify({ tests, errors, screenshot: '/tmp/opencode/facility-verification.jpg', dimensions: await page.evaluate(() => ({ width: document.documentElement.clientWidth, height: document.documentElement.clientHeight })) }, null, 2))
await context.close()
await browser.close()

